@page "/board"
@rendermode InteractiveServer
@using sv_5e7c06c3c42941c89fc718a8e5eebab9.Components.Board

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStatsBar Tasks="tasks" />
    <BoardSearchBar SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="row g-3">
        <BoardColumn Status="To Do"
                     Tasks="GetFilteredTasks("To Do")"
                     MoveLeftStatus="@null"
                     MoveRightStatus="In Progress"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated" />

        <BoardColumn Status="In Progress"
                     Tasks="GetFilteredTasks("In Progress")"
                     MoveLeftStatus="To Do"
                     MoveRightStatus="Done"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated" />

        <BoardColumn Status="Done"
                     Tasks="GetFilteredTasks("Done")"
                     MoveLeftStatus="In Progress"
                     MoveRightStatus="@null"
                     OnMoveTask="HandleMoveTask"
                     OnTaskCreated="HandleTaskCreated" />
    </div>
}

@code {
    [Inject] private ITaskService TaskService { get; set; } = default!;

    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        loading = true;
        errorMessage = null;
        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void HandleSearchChanged(string text)
    {
        searchText = text;
    }

    private async Task HandleMoveTask((int TaskId, string NewStatus) move)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(move.TaskId, move.NewStatus);
            var index = tasks.FindIndex(t => t.Id == move.TaskId);
            if (index >= 0)
            {
                var old = tasks[index];
                tasks[index] = old with { Status = move.NewStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        tasks.Add(task);
    }
}

