{"path": "/tmp/sv-5e7c06c3c42941c89fc718a8e5eebab9/Components/Board/BoardColumn.razor", "file_text": "
<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@Status</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body" style="min-height: 200px;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          OnMoveLeft="() => HandleMove(task, MoveLeftStatus!)"
                          OnMoveRight="() => HandleMove(task, MoveRightStatus!)" />
            }

            @if (showForm)
            {
                <AddTaskForm ColumnStatus="@Status"
                             OnTaskCreated="HandleTaskCreated"
                             OnCancel="() => showForm = false" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm w-100 mt-2" @onclick="() => showForm = true">
                    + Add Task
                </button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public string? MoveLeftStatus { get; set; }
    [Parameter] public string? MoveRightStatus { get; set; }
    [Parameter] public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool showForm;

    private bool CanMoveLeft => MoveLeftStatus is not null;
    private bool CanMoveRight => MoveRightStatus is not null;

    private async Task HandleMove(TaskItem task, string newStatus)
    {
        await OnMoveTask.InvokeAsync((task.Id, newStatus));
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}
"}

